    observePayroll: function(){
        if(this.payroll()){
            var cmpStatus = this.getStatusAction();
            var cmpWorkPayroll = this.getWorkPayrollAction();
            var cmpPrevPayroll = this.getPrevPayrollAction();
            var cmpNextPayroll = this.getNextPayrollAction();

            cmpStatus.setIconClass(this._payroll.icons[0].iconCls);
            cmpStatus.enable();
            this._payroll.previous? cmpPrevPayroll.enable(): cmpPrevPayroll.disable();
            this._payroll.next? cmpNextPayroll.enable(): cmpNextPayroll.disable();
            !this._payroll.is_working? cmpWorkPayroll.enable(): cmpWorkPayroll.disable();
            this.setParam('folha', this.payroll().pk);
            this.setFilterProperty('folha', this.payroll().pk, 100);
        }
        else{
            var cmpStatus = this.getStatusAction();
            var cmpWorkPayroll = this.getWorkPayrollAction();
            var cmpPrevPayroll = this.getPrevPayrollAction();
            var cmpNextPayroll = this.getNextPayrollAction();

            cmpStatus.setIconClass('icon-core icon-core-blank');
            cmpStatus.disable();
            cmpPrevPayroll.disable();
            cmpNextPayroll.disable();
            cmpWorkPayroll.disable();
            this.getStore().removeAll();
            this.setFilterProperty('folha', 0, 100, false);
        }
    },

    payroll: function(value, dispatch){
        dispatch = core.nullValue(dispatch, true);

        if(value !== undefined){
            this._payroll = value;

            if(dispatch) this.observePayroll();
        }
        else
            return this._payroll;
    },

    changeStatusFolha: function(statusType){
        var msg = false;

        if(statusType == 3)
            msg = 'Primeiro cheque se existem pendencias para esta folha, pois, ' +
                  'todas as pendencias de validação da folha ' + this.folha.description + ' serão aprovados por você.</br></br>' +
                  'Tem certeza que deseja mudar o status da folha de pagamento para fechado?';
        else
            msg = 'Tem certeza que deseja mudar o status da folha ' + this.folha.description + '?';

        Ext.Msg.show({
            title: 'Status da Folha de Pagamento',
            msg: msg,
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            fn: function(b) {

                if(b == 'no') return;

                Ext.Ajax.request({
                    url: toolkit.util.Normalize.controller_action(
                        'GFPLancador',
                        'update_status_folha'
                    ),
                    params: {
                        pk: this.folha.pk,
                        status: statusType
                    },
                    success: function(request) {
                        var obj = Ext.decode(request.responseText);

                        if(obj.success){
                            this.folha = obj.folha;
                            this.refreshContraCheque();
                        }
                        else alert(obj.message);
                    },
                    scope: this
                })
            },
            scope: this
        });
    },

    getCurrentPayroll: function(){
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action(
                'GFPPayroll',
                'working'
            ),
            method: 'GET',
            success: function(request) {
                //Type name of new folder
                var code = Ext.decode(request.responseText);
                if(code.payroll && code.payroll.id){
                    var payrollField = this.getPayrollField();
                    if(payrollField)
                        payrollField.setValue(code.payroll.id);
                }
                // this.payroll(code.payroll, true);
            },
            scope: this
        });
    },

    getPayroll: function(){
        return this._payroll;
    },

