    unsetPayroll: function(){
        this._payroll = null;
        var cmpStatus = this.getStatusAction();
        var cmpWorkPayroll = this.getWorkPayrollAction();
        var cmpPrevPayroll = this.getPrevPayrollAction();
        var cmpNextPayroll = this.getNextPayrollAction();

        cmpStatus.setIconClass('icon-core icon-core-blank');
        cmpStatus.disable();
        cmpPrevPayroll.disable();
        cmpNextPayroll.disable();
        cmpWorkPayroll.disable();
    },

    nextPeriod: function(){
        if(this.payroll() && this.payroll().next){
            var payrollField = this.getPayrollField();
            payrollField.setValue(this.payroll().next);
        }
    },

    previousPeriod: function(){
        if(this.payroll() && this.payroll().previous){
            var payrollField = this.getPayrollField();
            payrollField.setValue(this.payroll().previous);
        }
    },

    setWorkingPayroll: function(){
        if(this.payroll()){
            Ext.Ajax.request({
                url: toolkit.util.Normalize.controller_action('GFPPayroll', 'select'),
                params: { payroll: this.payroll().pk},
                success: function(request) {
                    var obj = Ext.decode(request.responseText);
                    if(!obj.success) {
                        Ext.MessageBox.show({
                           title: 'Erro',
                           msg: obj.message,
                           buttons: Ext.MessageBox.OK,
                           icon: Ext.MessageBox.ERROR
                        })
                    }else{
                        this.payroll(obj.payroll);
                    }
                },
                failure: function() {
                    Ext.MessageBox.show({
                       title: 'Erro',
                       msg: 'Ocorreu um erro inesperado',
                       buttons: Ext.MessageBox.OK,
                       icon: Ext.MessageBox.ERROR
                    })
                },
                scope: this
            });
        }else{
            Ext.MessageBox.show({
               title: 'Folha não selecionada',
               msg:'Nenhuma folha para selecionar!',
               buttons: Ext.MessageBox.OK,
               icon: Ext.MessageBox.WARN
            })
        }
    },

